package lt.viko.eif.imazolevska.jaxws_client;

import lt.viko.eif.imazolevska.jaxws.client.Director;
import lt.viko.eif.imazolevska.jaxws.client.Movie;

/**
 * Creates sample objects of the classes generated by wsimport for use in tests.
 */
public final class TestData {

    private TestData() {
    }

    /**
     * Creates the movie "Memento".
     *
     * @return sample movie
     */
    public static Movie memento() {
        Movie movie = new Movie();
        movie.setId(1);
        movie.setTitle("Memento");
        movie.setReleaseYear(2000);
        movie.setRating(8.4f);
        return movie;
    }

    /**
     * Creates the director Christopher Nolan with one movie.
     *
     * @return sample director
     */
    public static Director nolan() {
        Director.Movies movies = new Director.Movies();
        movies.getMovie().add(memento());

        Director director = new Director();
        director.setId(1);
        director.setFirstName("Christopher");
        director.setLastName("Nolan");
        director.setBirthYear(1970);
        director.setAverageRating(8.6f);
        director.setActive(true);
        director.setMainGenre("S");
        director.setMovies(movies);
        return director;
    }
}
